cd /tmp && python3 -c "
import itertools
def check(jobs):
    nums = [int(j.split('-')[1]) for j in jobs]
    if len(set(nums)) != len(nums) or nums != sorted(nums):
        return False
    if jobs.index('J-418') > jobs.index('J-402'):
        return False
    return True

base = ['J-401','J-415','J-402','J-409','J-418','J-407']
found = False
for perm in itertools.permutations(base):
    if check(list(perm)):
        found = True
        print('FOUND', perm)
        break
if not found:
    print('No permutation of these 6 jobs satisfies audit.py')

# also test minimal case of just the two required jobs
for perm in itertools.permutations(['J-418','J-402']):
    print(perm, check(list(perm)))
"
